scwin.closeWd = function() {
    return window.open('', '_self').close();
}
scwin.openWindow = function(url) {
    Popup = window.open(url, "Popup", 'toolbar=0,scrollbars=0,location=0,statusbar=0,menubar=0,resizable=0,width=750,height=500,left = 90,top = 90');
    Popup.focus();
}

scwin.setVal1 = function() {
    WebSquare.wUnit.getJq('#tbl1_container_scrollX').animate({scrollLeft:0}, 500);
}
scwin.setVal2 = function() {
    WebSquare.wUnit.getJq('#tbl1_container_scrollX').animate({scrollLeft:1000}, 500);
}
scwin.checkVal = function() {
    return (WebSquare.wUnit.getJq(WebSquare.wUnit.getJq('#tbl1_head_table tr').first()).find('th').last())[0].innerText == '최종점수';
}

scwin.unitTest1 = function() {
    //init
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "localStorage.setItem('isAllowShow', 'true')");
    WebSquare.wUnit.addCommand("set", "scwin.openWindow(window.location.href)");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.closeWd()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest2 = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "localStorage.setItem('isAllowShow', 'false')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");

    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest()
    //Created by: Quan.Nguyen
    //Created date: 03-Apr-2018
    if (localStorage.getItem("isAllowShow") == "true") {
        scwin.unitTest2();
    } else {
        scwin.unitTest1();
    }
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
